from pathlib import Path
p=Path("index.html")
s=p.read_text(encoding="utf-8")
def rep(old,new,label):
    global s
    if old not in s:
        if new in s:return
        raise SystemExit("missing "+label)
    s=s.replace(old,new,1)
rep("<title>ma.｜案件 v84</title>","<title>ma.｜案件 v86</title>","title")
rep("version:84,","version:86,","version")
rep('data-build="ma-project-v84"','data-build="ma-project-v86"',"build")
rep('const WORKSPACE_DOCK_KEY="maWorkspaceDockV84"','const WORKSPACE_DOCK_KEY="maWorkspaceDockV86"',"dock")
